SELECT id, name, description, price, stock, created_at, updated_at
FROM v_product_search


        AND name LIKE CONCAT('%', #{name}, '%')


        AND price >= #{minPrice}


        AND price <= #{maxPrice}


        AND stock >= #{minStock}


        AND stock <= #{maxStock}


ORDER BY 

    name
    price
    stock
    created_at
    id


    DESC
    ASC

LIMIT #{size} OFFSET #{page} * #{size}

SELECT COUNT(*)
FROM v_product_search


        AND name LIKE CONCAT('%', #{name}, '%')


        AND price >= #{minPrice}


        AND price <= #{maxPrice}


        AND stock >= #{minStock}


        AND stock <= #{maxStock}
